import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"编译与部署","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process"},{"text":"算子动态库和静态库编译","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/dynamic_static_lib_compilation"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/dynamic_static_lib_compilation.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/dynamic_static_lib_compilation.md","outlineHeaders":[{"level":2,"title":"算子动态库和静态库","slug":"算子动态库和静态库","link":"#算子动态库和静态库"},{"level":2,"title":"编译动态库","slug":"编译动态库","link":"#编译动态库"},{"level":2,"title":"编译静态库","slug":"编译静态库","link":"#编译静态库"},{"level":2,"title":"单算子调用场景集成","slug":"单算子调用场景集成","link":"#单算子调用场景集成"},{"level":3,"title":"动态库集成","slug":"动态库集成","link":"#动态库集成"},{"level":3,"title":"静态库集成","slug":"静态库集成","link":"#静态库集成"},{"level":3,"title":"静态库和动态库混合使用","slug":"静态库和动态库混合使用","link":"#静态库和动态库混合使用"},{"level":2,"title":"算子入图场景配置","slug":"算子入图场景配置","link":"#算子入图场景配置"},{"level":2,"title":"多厂商和同名动态库处理","slug":"多厂商和同名动态库处理","link":"#多厂商和同名动态库处理"},{"level":2,"title":"旧版工程模板说明","slug":"旧版工程模板说明","link":"#旧版工程模板说明"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787050286000}'),l={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/compilation_and_deployment/dynamic_static_lib_compilation.md"};function e(o,s,t,d,i,h){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>算子动态库和静态库编译</h1><p>本文是扩展内容，介绍如何将自定义算子工程编译为动态库或静态库，并在应用程序或图模式场景中使用这些库。常规部署场景优先参考<a href="./basic_process.html">编译与部署基本流程</a>生成<code>custom_opp_*.run</code>算子包；只有当应用需要直接链接算子库，或希望把算子库集成到其他工程中时，再考虑使用动态库或静态库编译。与<code>.run</code>算子包预先安装到OPP目录不同，动态库或静态库方式在进程拉起后会由运行时创建临时目录，将算子包结构恢复到临时目录中并从该目录加载算子相关文件，进程退出前再删除该临时目录。</p><h2 id="算子动态库和静态库">算子动态库和静态库<a class="header-anchor" href="#算子动态库和静态库">​</a></h2><p>算子动态库和静态库编译，是将算子核函数（Kernel）实现、Host侧Tiling实现、入图适配文件，以及自动生成的单算子调用代码编译链接成库文件的过程。编译后会同时生成单算子调用aclnn头文件和算子原型定义头文件，分别用于单算子调用和算子入图场景。</p><p>和<code>.run</code>算子包相比，动态库或静态库更适合被应用工程直接链接；<code>.run</code>算子包更适合安装到OPP的<code>vendors/&lt;vendor_name&gt;</code>路径后供运行环境使用。不同产物形态的典型使用方式如下。</p><table><thead><tr><th>产物形态</th><th>CMake配置</th><th>主要产物</th><th>典型使用方式</th></tr></thead><tbody><tr><td>算子包</td><td><code>TYPE RUN</code></td><td><code>custom_opp_*.run</code></td><td>安装到OPP的<code>vendors/&lt;vendor_name&gt;</code>路径，供运行环境使用。</td></tr><tr><td>动态库</td><td><code>TYPE SHARED</code></td><td><code>libcust_opapi.so</code></td><td>应用或图模式流程动态链接。</td></tr><tr><td>静态库</td><td><code>TYPE STATIC</code></td><td><code>lib\${vendor_name}.a</code></td><td>应用工程静态链接，通过aclnn方式执行算子。</td></tr></tbody></table><p>算子动态库和静态库编译支持以下产品范围：</p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div><div data-filter="A3"><ul><li>Atlas A3训练系列产品 / Atlas A3推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2训练系列产品 / Atlas A2推理系列产品</li></ul></div><p>开始前需完成以下准备：</p><ul><li>已完成算子原型定义、Host侧Tiling实现和核函数（Kernel）侧实现；</li><li>工程使用<code>find_package(ASC)</code>和<code>npu_op_package</code>组织编译；</li><li>已配置CANN环境变量，例如执行<code>source \${install_path}/cann/set_env.sh</code>；</li><li>已在<code>CMakePresets.json</code>或CMake命令中配置<code>vendor_name</code>、<code>ASCEND_COMPUTE_UNIT</code>、<code>CMAKE_INSTALL_PREFIX</code>等参数。</li></ul><h2 id="编译动态库">编译动态库<a class="header-anchor" href="#编译动态库">​</a></h2><p>动态库编译时，将<code>npu_op_package</code>的<code>TYPE</code>设置为<code>SHARED</code>。以<a href="../aclnn_quick_start.html">快速入门</a>里的AddCustom为例，将顶层CMakeLists.txt里的npu_op_package配置修改如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">set</span><span class="p">(</span><span class="s">package_name</span><span class="w"> </span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="p">)</span>
<span class="nb">npu_op_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">TYPE</span><span class="w"> </span><span class="s">SHARED</span>
<span class="w">    </span><span class="s">CONFIG</span>
<span class="w">        </span><span class="s">INSTALL_PATH</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_INSTALL_PREFIX</span><span class="o">}</span>
<span class="p">)</span>
</code></pre></div><p>执行编译和安装：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>install<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p><code>TYPE RUN</code>场景通常执行<code>package</code>目标，生成<code>custom_opp_*.run</code>，后续再运行该<code>.run</code>包安装到目标OPP路径。<code>TYPE SHARED</code>和<code>TYPE STATIC</code>场景通常执行<code>install</code>目标，直接将头文件、库文件和CMake package配置安装到<code>\${CMAKE_INSTALL_PREFIX}</code>，供应用工程通过<code>find_package</code>或直接链接方式集成。</p></div><p>编译成功后，主要产物位于<code>\${CMAKE_INSTALL_PREFIX}</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>├── include
│   ├── aclnn_*.h       // 单算子调用aclnn头文件
│   └── op_proto.h      // 算子原型定义头文件
└── lib
    ├── cmake
    │   └── \${vendor_name}
    │       ├── \${vendor_name}-config.cmake  // 安装文件，定义了项目中的配置选项和变量
    │       └── \${vendor_name}-targets.cmake // 安装文件，定义动态库的构建目标\${vendor_name}::\${vendor_name}，便于开发者使用动态库，自动处理库的依赖关系
    └── libcust_opapi.so    // 动态库libcust_opapi.so，用于动态链接
</code></pre></div><h2 id="编译静态库">编译静态库<a class="header-anchor" href="#编译静态库">​</a></h2><p>静态库编译时，将<code>npu_op_package</code>的<code>TYPE</code>设置为<code>STATIC</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">set</span><span class="p">(</span><span class="s">package_name</span><span class="w"> </span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="p">)</span>
<span class="nb">npu_op_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">TYPE</span><span class="w"> </span><span class="s">STATIC</span>
<span class="w">    </span><span class="s">CONFIG</span>
<span class="w">        </span><span class="s">INSTALL_PATH</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_INSTALL_PREFIX</span><span class="o">}</span>
<span class="p">)</span>
</code></pre></div><p>执行编译和安装：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>cmake<span class="w"> </span>-S<span class="w"> </span>.<span class="w"> </span>-B<span class="w"> </span>build_out<span class="w"> </span>--preset<span class="o">=</span>default
cmake<span class="w"> </span>--build<span class="w"> </span>build_out<span class="w"> </span>--target<span class="w"> </span>binary<span class="w"> </span>install<span class="w"> </span>-j<span class="k">$(</span>nproc<span class="k">)</span>
</code></pre></div><p>编译成功后，主要产物位于<code>\${CMAKE_INSTALL_PREFIX}</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>├── include
│   ├── aclnn_*.h   // 单算子调用aclnn头文件
│   └── op_proto.h  // 算子原型定义头文件
└── lib
    ├── cmake
    │   └── \${vendor_name}
    │       ├── \${vendor_name}-config.cmake  // 安装文件，定义了项目中的配置选项和变量
    │       └── \${vendor_name}-targets.cmake // 安装文件，定义静态库的构建目标\${vendor_name}::\${vendor_name}，便于开发者使用静态库，自动处理库的依赖关系
    └── lib\${vendor_name}.a // 算子静态库
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p><code>TYPE SHARED</code>和<code>TYPE STATIC</code>是两种产物形态。实际生成哪些库，以本次<code>npu_op_package</code>的<code>TYPE</code>配置和安装目录中的产物为准。</p></div><h2 id="单算子调用场景集成">单算子调用场景集成<a class="header-anchor" href="#单算子调用场景集成">​</a></h2><p>动态库静态库调用之前，需要把自定义算子包路径添加到<code>LD_LIBRARY_PATH</code>环境变量的首部，供系统动态链接器查找算子动态库，执行以下命令：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1"># \${CMAKE_INSTALL_PREFIX}需要换成自定义算子包路径的绝对路径</span>
<span class="nb">export</span><span class="w"> </span><span class="nv">LD_LIBRARY_PATH</span><span class="o">=</span><span class="si">\${</span><span class="nv">CMAKE_INSTALL_PREFIX</span><span class="si">}</span>/lib/:<span class="si">\${</span><span class="nv">LD_LIBRARY_PATH</span><span class="si">}</span>
</code></pre></div><p>之后调用方的应用工程可以通过<code>find_package</code>导入算子库，然后链接到自己的可执行文件或业务库中。以<a href="../aclnn_quick_start.html#%E8%B0%83%E7%94%A8%E7%AE%97%E5%AD%90">快速入门</a>里的AddCustom调用为例，向CMakeLists.txt里添加<code>\${vendor_name}</code>库搜索，并链接，示例如下：</p><h3 id="动态库集成">动态库集成<a class="header-anchor" href="#动态库集成">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">find_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="w"> </span><span class="s">REQUIRED</span><span class="w">    </span><span class="c"># \${vendor_name}为编译生成的算子package名称，需要用户替换为实际的算子package名称</span>
<span class="w">    </span><span class="s">PATHS</span><span class="w"> </span><span class="o">\${</span><span class="nv">CUST_PKG_PATH</span><span class="o">}</span><span class="w">  </span><span class="c"># \${CUST_PKG_PATH}需要用户替换为编译生成的算子package的存放路径，</span>
<span class="w">    </span><span class="s">NO_DEFAULT_PATH</span>
<span class="p">)</span>

<span class="nb">target_link_libraries</span><span class="p">(</span><span class="s">op_runner</span><span class="w"> </span><span class="s">PRIVATE</span><span class="w"> </span><span class="c"># op_runner需要替换成调用方的目标名</span>
<span class="w">    </span><span class="s">nnopbase</span>
<span class="w">    </span><span class="s">acl_rt</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="s">::</span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="w">  </span><span class="c"># 已自动包含相关的target依赖，需要把\${vendor_name}替换为实际的算子package名称</span>
<span class="p">)</span>
</code></pre></div><p>其中\${CUST_PKG_PATH}是\${CMAKE_INSTALL_PREFIX}/lib/cmake/\${vendor_name}。<code>find_package(\${vendor_name} ...)</code>导入的目标名为<code>\${vendor_name}::\${vendor_name}</code>，该目标在<code>TYPE SHARED</code>模式下指向<code>libcust_opapi.so</code>。</p><h3 id="静态库集成">静态库集成<a class="header-anchor" href="#静态库集成">​</a></h3><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">find_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="w"> </span><span class="s">REQUIRED</span><span class="w">    </span><span class="c"># \${vendor_name}为编译生成的算子package名称，需要用户替换为实际的算子package名称</span>
<span class="w">    </span><span class="s">PATHS</span><span class="w"> </span><span class="o">\${</span><span class="nv">CUST_PKG_PATH</span><span class="o">}</span><span class="w">  </span><span class="c"># \${CUST_PKG_PATH}需要用户替换为编译生成的算子package的存放路径，</span>
<span class="w">    </span><span class="s">NO_DEFAULT_PATH</span>
<span class="p">)</span>

<span class="nb">target_link_libraries</span><span class="p">(</span><span class="s">op_runner</span><span class="w"> </span><span class="s">PRIVATE</span><span class="w"> </span><span class="c"># op_runner需要替换成调用方的目标名</span>
<span class="w">    </span><span class="s">nnopbase</span>
<span class="w">    </span><span class="s">rt2_registry</span>
<span class="w">    </span><span class="s">acl_rt</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="s">::</span><span class="o">\${</span><span class="nv">vendor_name</span><span class="o">}</span><span class="w">  </span><span class="c"># 已自动包含相关的target依赖，需要把\${vendor_name}替换为实际的算子package名称</span>
<span class="p">)</span>
</code></pre></div><p><code>\${vendor_name}::\${vendor_name}</code>在<code>TYPE STATIC</code>模式下指向<code>lib\${vendor_name}.a</code>。 静态库集成的完整样例可参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/99_acl_based/00_acl_compilation/custom_op_static_lib">custom_op_static_lib</a>。</p><h3 id="静态库和动态库混合使用">静态库和动态库混合使用<a class="header-anchor" href="#静态库和动态库混合使用">​</a></h3><p>如果一个应用同时集成多个算子库，可分别指定各自的package查找路径：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">find_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">vendor_name1</span><span class="o">}</span><span class="w"> </span><span class="s">REQUIRED</span><span class="w">     </span><span class="c"># \${vendor_name1}为编译生成的算子package名称</span>
<span class="w">    </span><span class="s">PATHS</span><span class="w"> </span><span class="o">\${</span><span class="nv">CUST_PKG_PATH_1</span><span class="o">}</span><span class="w">              </span><span class="c"># \${CUST_PKG_PATH_1}为编译生成的算子package的存放路径</span>
<span class="w">    </span><span class="s">NO_DEFAULT_PATH</span>
<span class="p">)</span>
<span class="nb">find_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">vendor_name2</span><span class="o">}</span><span class="w"> </span><span class="s">REQUIRED</span><span class="w">     </span><span class="c"># \${vendor_name2}为编译生成的算子package名称</span>
<span class="w">    </span><span class="s">PATHS</span><span class="w"> </span><span class="o">\${</span><span class="nv">CUST_PKG_PATH_2</span><span class="o">}</span><span class="w">              </span><span class="c"># \${CUST_PKG_PATH_2}为编译生成的算子package的存放路径</span>
<span class="w">    </span><span class="s">NO_DEFAULT_PATH</span>
<span class="p">)</span>

<span class="nb">target_link_libraries</span><span class="p">(</span><span class="s">op_runner</span><span class="w"> </span><span class="s">PRIVATE</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">vendor_name1</span><span class="o">}</span><span class="s">::</span><span class="o">\${</span><span class="nv">vendor_name1</span><span class="o">}</span><span class="w">    </span><span class="c"># 已自动包含相关的静态库target依赖</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">vendor_name2</span><span class="o">}</span><span class="s">::</span><span class="o">\${</span><span class="nv">vendor_name2</span><span class="o">}</span><span class="w">    </span><span class="c"># 已自动包含相关的静态库target依赖</span>
<span class="p">)</span>
</code></pre></div><h2 id="算子入图场景配置">算子入图场景配置<a class="header-anchor" href="#算子入图场景配置">​</a></h2><p>算子入图场景下，需要配置ASCEND_CUSTOM_OPP_PATH环境变量，将动态库libcust_opapi.so所在目录添加到该环境变量首部。由GE框架在图编译和执行时根据该环境变量搜索算子动态库并使用。环境变量位置越靠前，算子的优先级越高。</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">export</span><span class="w"> </span><span class="nv">ASCEND_CUSTOM_OPP_PATH</span><span class="o">=</span><span class="si">\${</span><span class="nv">CMAKE_INSTALL_PREFIX</span><span class="si">}</span>/lib/:<span class="si">\${</span><span class="nv">ASCEND_CUSTOM_OPP_PATH</span><span class="si">}</span>
</code></pre></div><p>动态库编译和<a href="basic_process.html">算子包编译</a>功能同时使用时，前者生成的动态库优先级更高。 如下示例中，path1和path3是算子包的指定安装目录，path2和path4是动态库编译时的<code>CMAKE_INSTALL_PREFIX</code>，则编译产物的优先级为2&gt;4&gt;1&gt;3。</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nv">ASCEND_CUSTOM_OPP_PATH</span><span class="o">=</span>&lt;path1&gt;/vendors/vendor_name1:&lt;path2&gt;/lib/:&lt;path3&gt;/vendors/vendor_name3:&lt;path4&gt;/lib/
</code></pre></div><p>如果开发者通过Ascend Graph进行图开发，除了配置环境变量的方式，也可以采用直接在应用程序的编译文件中链接动态库libcust_opapi.so的方式。Ascend Graph图开发的相关信息请参考<a href="https://www.hiascend.com/document/redirect/CannCommunityGraphguide">《图引擎开发指南》</a>。动态库链接方式的so加载优先级高于环境变量配置方式。</p><h2 id="多厂商和同名动态库处理">多厂商和同名动态库处理<a class="header-anchor" href="#多厂商和同名动态库处理">​</a></h2><p>多个算子工程生成的动态库默认都叫<code>libcust_opapi.so</code>。多个厂商的算子库集成到一个项目时，如果只是通过不同安装路径分别查找和链接，可以用不同的<code>CUST_PKG_PATH</code>区分。</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c"># 分别指定不同厂商的算子库路径</span>
<span class="nb">find_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">vendor_name1</span><span class="o">}</span><span class="w"> </span><span class="s">REQUIRED</span>
<span class="w">    </span><span class="s">PATHS</span><span class="w"> </span><span class="o">\${</span><span class="nv">CUST_PKG_PATH_1</span><span class="o">}</span><span class="w">              </span><span class="c">#指向厂商1的算子库安装路径</span>
<span class="w">    </span><span class="s">NO_DEFAULT_PATH</span>
<span class="p">)</span>
<span class="nb">find_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">vendor_name2</span><span class="o">}</span><span class="w"> </span><span class="s">REQUIRED</span>
<span class="w">    </span><span class="s">PATHS</span><span class="w"> </span><span class="o">\${</span><span class="nv">CUST_PKG_PATH_2</span><span class="o">}</span><span class="w">              </span><span class="c">#指向厂商2的算子库安装路径</span>
<span class="w">    </span><span class="s">NO_DEFAULT_PATH</span>
<span class="p">)</span>

<span class="nb">target_link_libraries</span><span class="p">(</span><span class="s">op_runner</span><span class="w"> </span><span class="s">PRIVATE</span>
<span class="w">    </span><span class="s">...</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">vendor_name1</span><span class="o">}</span><span class="s">::</span><span class="o">\${</span><span class="nv">vendor_name1</span><span class="o">}</span>
<span class="w">    </span><span class="o">\${</span><span class="nv">vendor_name2</span><span class="o">}</span><span class="s">::</span><span class="o">\${</span><span class="nv">vendor_name2</span><span class="o">}</span>
<span class="w">    </span><span class="s">...</span>
<span class="p">)</span>
</code></pre></div><p>如果需要将多个动态库集成到同一个公共动态库，或在同一应用中避免文件名冲突，可在编译前顶层的CMakeLists.txt里为动态库设置不同输出名，之后再编译安装动态库，在npu_op_package之后添加set_target_properties修改：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">npu_op_package</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span>
<span class="w">    </span><span class="s">TYPE</span><span class="w"> </span><span class="s">SHARED</span>
<span class="w">    </span><span class="s">CONFIG</span>
<span class="w">        </span><span class="s">INSTALL_PATH</span><span class="w"> </span><span class="o">\${</span><span class="nv">CMAKE_BINARY_DIR</span><span class="o">}</span><span class="s">/</span>
<span class="p">)</span>

<span class="nb">set_target_properties</span><span class="p">(</span><span class="o">\${</span><span class="nv">package_name</span><span class="o">}</span><span class="w"> </span><span class="s">PROPERTIES</span>
<span class="w">    </span><span class="s">OUTPUT_NAME</span><span class="w"> </span><span class="s">xxxxxxx</span>
<span class="p">)</span>
</code></pre></div><h2 id="旧版工程模板说明">旧版工程模板说明<a class="header-anchor" href="#旧版工程模板说明">​</a></h2><p>部分旧版工程模板通过<code>ASCEND_PACK_SHARED_LIBRARY=True</code>控制动态库和静态库编译：</p><div class="code-block"><div class="code-header"><span class="lang-label">JSON</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nt">&quot;ASCEND_PACK_SHARED_LIBRARY&quot;</span><span class="p">:</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="nt">&quot;type&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;BOOL&quot;</span><span class="p">,</span>
<span class="w">    </span><span class="nt">&quot;value&quot;</span><span class="p">:</span><span class="w"> </span><span class="s2">&quot;True&quot;</span>
<span class="p">}</span>
</code></pre></div><p>如果工程已经使用<code>npu_op_package(... TYPE RUN/SHARED/STATIC ...)</code>，则产物形态由<code>TYPE</code>参数决定，不再通过<code>ASCEND_PACK_SHARED_LIBRARY</code>控制。</p><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="./basic_process.html">编译与部署基本流程</a> — 基础编译配置和<code>npu_op_package</code>用法。</li><li><a href="../invocation/single_operator_api_call.html">单算子API调用</a> — 使用生成的aclnn接口调用算子。</li></ul></article></div>`,1)])])}const r=a(l,[["render",e]]);export{_ as __pageData,r as default};
